import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.0
    # Torso: width=1.0, height=0.8, density=0.8 (mass: 0.64 kg)
    torso = sandbox.add_beam(x=start_x, y=start_y, width=1.0, height=0.8, density=0.8)
    sandbox.set_material_properties(torso, friction=0.008)

    # Wheels: radius=0.6, density=0.2 (mass per wheel: ~0.226 kg)
    WHEEL_RADIUS = 0.6
    wheel_y = 1.0 + WHEEL_RADIUS  # y=1.6m (ground level + radius)
    wheel1 = sandbox.add_wheel(x=start_x - 0.5, y=wheel_y, radius=WHEEL_RADIUS, density=0.2)
    wheel2 = sandbox.add_wheel(x=start_x + 0.5, y=wheel_y, radius=WHEEL_RADIUS, density=0.2)
    sandbox.set_material_properties(wheel1, friction=0.008)
    sandbox.set_material_properties(wheel2, friction=0.008)

    # Joints connect torso to wheels at (9.5, 1.6) and (10.5, 1.6)
    joint1 = sandbox.add_joint(torso, wheel1, (start_x - 0.5, wheel_y), type='pivot')
    joint2 = sandbox.add_joint(torso, wheel2, (start_x + 0.5, wheel_y), type='pivot')

    return {"body": torso, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None
    if torso is not None:
        # Drive wheels forward until target x=25.0
        if torso.position.x < 25.0:
            rotation_speed = -0.2  # within joint angle limit [-0.2094, 0.2094]
        else:
            rotation_speed = 0.0
        for j in joints:
            sandbox.set_motor(j, rotation_speed, max_torque=100.0)
